import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  Inject,
  Input,
  OnInit,
  Optional,
  Output,
  Self,
  ViewChild,
  ViewEncapsulation
} from '@angular/core';
import {
  AbstractControl,
  FormGroupDirective,
  FormsModule,
  NgControl,
  NgForm,
  ValidationErrors,
  ValidatorFn
} from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MAT_FORM_FIELD_DEFAULT_OPTIONS, MatFormFieldModule } from '@angular/material/form-field';
import { NgClass, NgIf } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { DateFnsAdapter } from '@angular/material-date-fns-adapter';
import { MatInput, MatInputModule } from '@angular/material/input';
import { coerceBooleanProperty } from '@angular/cdk/coercion';
import { A11yModule } from '@angular/cdk/a11y';

import { ptBR } from 'date-fns/locale';

// @ts-ignore
import Inputmask from 'inputmask/dist/inputmask.es6.js';

import { BaseComponent } from 'sidsc-components/core';
import { DscTooltipModule } from 'sidsc-components/dsc-tooltip';

export const DEFAULT_DATE_FORMATS = {
  parse: { dateInput: 'dd/MM/yyyy' },
  display: {
    dateInput: 'dd/MM/yyyy',
    monthYearLabel: 'MMM yyyy',
    dateA11yLabel: 'dd/MM/yyyy',
    monthYearA11yLabel: 'MMMM yyyy',
  },
};

export const MONTH_YEAR_DATE_FORMATS = {
  parse: { dateInput: 'MM/yyyy' },
  display: {
    dateInput: 'MM/yyyy',
    monthYearLabel: 'MMM yyyy',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'MMMM yyyy',
  },
};

export function dateFormatsFactory(){
  return {
    parse: {...DEFAULT_DATE_FORMATS.parse},
    display: {...DEFAULT_DATE_FORMATS.display}
  };
}

export function getDateFormats(component: DscDatepickerComponent) {
  const format = component.effectiveDateFormat;

  return {
    parse: { dateInput: format },
    display: {
      dateInput: format,
      monthYearLabel: 'MMM yyyy',
      dateA11yLabel: 'dd/MM/yyyy',
      monthYearA11yLabel: 'MMMM yyyy',
    },
  };
}

@Component({
  selector: 'dsc-datepicker',
  standalone: true,
  encapsulation: ViewEncapsulation.None,
  imports: [
    FormsModule,
    MatFormFieldModule,
    MatButtonModule,
    MatIconModule,
    MatTooltipModule,
    DscTooltipModule,
    MatInputModule,
    NgIf,
    NgClass,
    MatDatepickerModule,
    A11yModule
  ],
  templateUrl: './dsc-datepicker.component.html',
  styleUrls: ['./dsc-datepicker.component.scss'],
  providers: [
    { provide: MAT_DATE_LOCALE, useValue: ptBR },
    { provide: DateAdapter, useClass: DateFnsAdapter, deps: [MAT_DATE_LOCALE] },
    {
      provide: MAT_DATE_FORMATS,
      useFactory: dateFormatsFactory
    },
    { provide: MAT_FORM_FIELD_DEFAULT_OPTIONS, useValue: { appearance: 'outline' } }
  ]
})
export class DscDatepickerComponent extends BaseComponent<Date> implements OnInit, AfterViewInit {
  
  @ViewChild(MatInput, { static: true })
  matInput!: MatInput;

  @ViewChild('dateInputRef', { static: true, read: ElementRef })
  dateInputElement!: ElementRef<HTMLInputElement>;

  @Input()
  maxDate!: Date | null;

  @Input()
  minDate!: Date | null;

  private _customDateFormat: string | null = null;

  @Input() 
  get customDateFormat(): string | null {
    return this._customDateFormat;
  }

  set customDateFormat(value: string | null){
    this._customDateFormat = value;
    this._updateDateFormats();
    this._maskInit();
  }

  get effectiveDateFormat(): string {
    if (this._customDateFormat) return this._customDateFormat;
    return this._monthYear ? 'MM/yyyy' : 'dd/MM/yyyy';
  }

  @ViewChild('picker') picker!: any;

  private _monthYear = false;

  @Input()
  get monthYear(): boolean {
    return this._monthYear;
  }

  set monthYear(value: boolean) {
    this._monthYear = coerceBooleanProperty(value);
    this._updateDateFormats();
    this._maskInit();
  }

  @Input()
  datepickerFilter!: (date: Date | null) => boolean;

  @Input()
  get touchUi(): boolean {
    return this._touchUi;
  }

  set touchUi(value: boolean | string) {
    this._touchUi = coerceBooleanProperty(value);
  }

  private _touchUi = false;

  isActive: boolean = false;
  
  tooltipId = `tt-${cryptoRandom()}`;

  @Output()
  dateChange: EventEmitter<any> = new EventEmitter<any>();

  @Output()
  dateInput: EventEmitter<any> = new EventEmitter<any>();

  @Output()
  opened: EventEmitter<any> = new EventEmitter<any>();

  @Output()
  closed: EventEmitter<any> = new EventEmitter<any>();

  constructor(@Optional() @Self() public ngControl: NgControl,
              @Optional() parentForm: NgForm,
              @Optional() parentFormGroup: FormGroupDirective,
              @Optional() private _dateAdapter: DateAdapter<Date>,
              @Inject(MAT_DATE_FORMATS) private _dateFormats: any,
  ) {
    super(ngControl, parentForm, parentFormGroup);
    if (this.ngControl) this.ngControl.valueAccessor = this;
    if (!this._dateAdapter) throw Error('MatDatepicker: No provider found for DateAdapter.',);
  }

  ngOnInit(): void {
    this._initValidators();
    this._updateDateFormats();
  }

  private _initValidators(): void {
    if (this.ngControl) {
      const control = this.ngControl.control;
      control?.addValidators(this._getValidators());
      control?.updateValueAndValidity();
    }
  }

  ngAfterViewInit(): void {
    this._maskInit();
  }

  private _updateDateFormats(): void {
    const fmt = this.effectiveDateFormat;
    this._dateFormats.parse.dateInput = fmt
    this._dateFormats.display.dateInput = fmt
  }

  get computedPlaceholder(): string {
    if (this.placeholder) return this.placeholder;

    if (this.customDateFormat){
      return this.customDateFormat.replace(/d/gi, 'D').replace(/M/g, 'M').replace(/y/gi, 'A');
    }

    return this.monthYear ? 'MM/AAAA' : 'DD/MM/AAAA';
  }

  
  private _maskInit(): void {
    if (!this.dateInputElement || !this.dateInputElement.nativeElement) return;

    const input = this.dateInputElement.nativeElement as HTMLInputElement;
    const currentValue = input.value;
    Inputmask.remove(input);

    const format = this.effectiveDateFormat;
    const tokens: string[] = format.match(/(d+|M+|y+)/g) || [];
    const separators: string[] = format.split(/d+|M+|y+/).filter(Boolean);

    const maskPattern = this._generateMaskPattern(tokens, separators);
    const definitions = this._createDefinitions(tokens, separators);

    this._applyInputMask(input, maskPattern, definitions);

    if (currentValue) input.value = currentValue;
  }

  private _generateMaskPattern(tokens: string[], separators: string[]): string {
    return tokens.map((token, i) => '9'.repeat(token.length) + (separators[i] || '')).join('');
  }

  private _createDefinitions(tokens: string[], separators: string[]): Record<string, any> {
    return {
      '9': {
        validator: (chrs: string, maskset: { buffer: string[] }, pos: number): boolean => {
          let charIndex = 0;

          for (let i = 0; i < tokens.length; i++) {
            const token = tokens[i];
            const start = charIndex;
            const end = charIndex + token.length - 1;

            if (pos >= start && pos <= end) {
              if (token.startsWith('d')) return this._validateDay(chrs, pos, start, maskset);
              if (token.startsWith('M')) return this._validateMonth(chrs, pos, start, maskset);
              return this._validateYear(chrs, pos, start, maskset, token.length);
            }

            charIndex += token.length + (separators[i]?.length || 0);
          }

          return /^\d$/.test(chrs);
        }
      }
    };
  }

  
  private _validateDay(chrs: string, pos: number, start: number, maskset: { buffer: string[] }): boolean {
    if (pos === start) return /^[0-3]$/.test(chrs);
    if (pos === start + 1) {
      const firstDigit = maskset.buffer[start];
      if (firstDigit === '0') return /^[1-9]$/.test(chrs); // Bloqueia 00
      if (firstDigit === '3') return /^[0-1]$/.test(chrs);
      return /^[0-9]$/.test(chrs);
    }
    return /^[0-9]$/.test(chrs);
  }

  private _validateMonth(chrs: string, pos: number, start: number, maskset: { buffer: string[] }): boolean {
    if (pos === start) {
      return /^[0-1]$/.test(chrs);
    }

    if (pos === start + 1) {
      const firstDigit = maskset.buffer[start];

      if (firstDigit === '0' && !/^[1-9]$/.test(chrs)) return false;
      if (firstDigit === '1' && !/^[0-2]$/.test(chrs)) return false;

      const dayMeta = this._getTokenMeta('d');
      let day: number | null = null;
      if (dayMeta) {
        day = this._readNumberFromBuffer(maskset.buffer, dayMeta.start, dayMeta.len);
      }

      if (day !== null) {
        const month = parseInt(`${firstDigit}${chrs}`, 10);

        this.monthValidation(month);

        this.dayValidation(day, month);

        if (this.isInvalidDayForMonth(day, month)) return false;
        if (month === 2 && day > 29) return false;
      }

      return true;
    }

    return /^[0-9]$/.test(chrs);
  }

  private isInvalidDayForMonth(day: number, month: number): boolean {
    const monthsWith30OrLess = [2, 4, 6, 9, 11];
    return day === 31 && monthsWith30OrLess.includes(month);
  }

  private monthValidation(month: number): boolean {
    return month >= 1 && month <= 12;
  }

  private dayValidation(day: number ,month: number) {
    return day === 30 && month === 2;
  }

  private _validateYear(chrs: string, pos: number, start: number, maskset: { buffer: string[] }, yearLen: number): boolean {
    if (!this._isDigit(chrs)) return false;
    if (!this._isLastYearDigit(pos, start, yearLen)) return true;

    const day = this._readDay(maskset);
    const month = this._readMonth(maskset);
    if (day == null || month == null) return true;

    const year = this._buildProvisionalYear(chrs, pos, start, yearLen, maskset);
    if (year == null) return true;

    return this._isValidDateConsideringLeapYear(day, month, year);
  }
  
  private _isDigit(ch: string): boolean {
    return /^\d$/.test(ch);
  }
  
  private _isLastYearDigit(pos: number, start: number, yearLen: number): boolean {
    return pos === start + yearLen - 1;
  }

  private _readDay(maskset: { buffer: string[] }): number | null {
    const meta = this._getTokenMeta('d');
    return meta ? this._readNumberFromBuffer(maskset.buffer, meta.start, meta.len) : null;
  }

  private _readMonth(maskset: { buffer: string[] }): number | null {
    const meta = this._getTokenMeta('M');
    return meta ? this._readNumberFromBuffer(maskset.buffer, meta.start, meta.len) : null;
  }
  
  private _buildProvisionalYear(chrs: string, pos: number, start: number, len: number, maskset: { buffer: string[] }): number | null {
    const digits = [...maskset.buffer.slice(start, start + len)];
    digits[pos - start] = chrs;

    if (digits.some(d => !this._isDigit(d))) return null;

    return parseInt(digits.join(''), 10);
  }

  private _isValidDateConsideringLeapYear(day: number, month: number, year: number): boolean {
    return month !== 2 || (day <= 29 && (day !== 29 || this._isLeapYear(year)));
  }

  private _isLeapYear(y: number): boolean {
    return (y % 400 === 0) || (y % 4 === 0 && y % 100 !== 0);
  }

  private _getTokenMeta(tokenChar: 'd' | 'M' | 'y'): { start: number; len: number } | null {
    const format = this.effectiveDateFormat;
    const tokens: string[] = format.match(/(d+|M+|y+)/g) || [];
    const separators: string[] = format.split(/d+|M+|y+/).filter(Boolean);

    let index = 0;
    for (let i = 0; i < tokens.length; i++) {
      const t = tokens[i];
      const len = t.length;
      if (t.startsWith(tokenChar)) {
        return { start: index, len };
      }
      index += len + (separators[i]?.length || 0);
    }
    return null;
  }

  private _readNumberFromBuffer(buffer: string[], start: number, len: number): number | null {
    const str = buffer.slice(start, start + len).join('');
    const onlyDigits = new RegExp(`^\\d{${len}}$`);
    return onlyDigits.test(str) ? parseInt(str, 10) : null;
  }

  private _applyInputMask(input: HTMLInputElement, maskPattern: string, definitions: any): void {

    const maskSkeleton =
    this.customDateFormat
      ? this.customDateFormat.replace(/d/gi, 'D').replace(/y/gi, 'A')
      : (this.monthYear ? 'MM/AAAA' : 'DD/MM/AAAA');

    const im = new Inputmask({
      mask: maskPattern,
      placeholder: maskSkeleton,
      clearIncomplete: true,
      showMaskOnHover: false,
      showMaskOnFocus: true,
      definitions,
      oncomplete: () => {
        const value = input.value;
        const yearMatch = value.match(/(\d{4})$/);
        if (yearMatch && yearMatch[1] === '0000') {
          input.value = value.replace(/0000$/, '2000');
        }
      }
    });

    im.mask(input);
  }


  onDateSelection(date: Date): void {
    if(this.monthYear){
      const format = this.customDateFormat || MONTH_YEAR_DATE_FORMATS.display.dateInput;
      const formattedValue = this._dateAdapter.format(date, format);
      this.dateInputElement.nativeElement.value = formattedValue;
      this.val = date;
      this.dateChange.emit(date);
      this.picker.close();
    } 
  }

  private _getValidators(): ValidatorFn[] {
    return [this._minValidator, this._maxValidator, this._filterValidator];
  }

  private _filterValidator: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
    const controlValue = this._dateAdapter.getValidDateOrNull(this._dateAdapter.deserialize(control.value));
    return !controlValue || this._matchesFilter(controlValue)
      ? null
      : {'matDatepickerFilter': true};
  };

  private _matchesFilter(value: Date | null): boolean {
    const filter = this.datepickerFilter;
    return !filter || filter(value);
  }

  private _minValidator: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
    const controlValue = this._dateAdapter.getValidDateOrNull(this._dateAdapter.deserialize(control.value));
    const min = this.minDate;
    return !min || !controlValue || this._dateAdapter.compareDate(min, controlValue) <= 0
      ? null : {'matDatepickerMin': {'min': min, 'actual': controlValue}};
  };

  private _maxValidator: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
    const controlValue = this._dateAdapter.getValidDateOrNull(this._dateAdapter.deserialize(control.value));
    const max = this.maxDate;
    return !max || !controlValue || this._dateAdapter.compareDate(max, controlValue) >= 0
      ? null : {'matDatepickerMax': {'max': max, 'actual': controlValue}};
  };

  get formFieldClasses(): string[] {
    return [
      this.ngControl && this.ngControl.value?.length
        ? 'mat-mdc-form-field--filled'
        : 'mat-mdc-form-field--empty',
      this.readOnly ? 'mat-mdc-form-field--readonly' : '',
      this.ngControl &&
      this.ngControl.invalid &&
      (this.ngControl.touched || this.ngControl.dirty) &&
      !this.readOnly
        ? 'error-field'
        : '',
        (this.isActive && !this.errorText) || (this.ngControl && this.ngControl.value?.length)
        ? 'active-field'
        : ''
    ].filter(Boolean);
  }
}

function cryptoRandom() {
  return Math.random().toString(36).slice(2);
}
